import{_ as a,o as t,c as i,am as r}from"./chunks/framework.BwQOZRag.js";const h=JSON.parse('{"title":"Glossaire","description":"","frontmatter":{"titre":"Glossaire"},"headers":[],"relativePath":"glossaire.md","filePath":"glossaire.md"}'),o={name:"glossaire.md"};function n(s,e,l,u,d,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="glossaire" tabindex="-1">Glossaire <a class="header-anchor" href="#glossaire" aria-label="Permalink to &quot;Glossaire&quot;">​</a></h1><h3 id="accessibilite-aa-wcag" tabindex="-1">Accessibilité AA (WCAG) <a class="header-anchor" href="#accessibilite-aa-wcag" aria-label="Permalink to &quot;Accessibilité AA (WCAG)&quot;">​</a></h3><p>Niveau de règles qui rend un écran utilisable par tous, y compris avec un lecteur d&#39;écran ou au clavier : contraste, libellés, ordre de lecture. Les WCAG sont les règles internationales de référence.</p><h3 id="analyse-d-impact" tabindex="-1">Analyse d&#39;impact <a class="header-anchor" href="#analyse-d-impact" aria-label="Permalink to &quot;Analyse d&#39;impact&quot;">​</a></h3><p>Repérer ce qu&#39;un changement touche (modules modifiés, et tout ce qui les utilise) pour choisir ce qu&#39;il faut retester.</p><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><p>Point d&#39;entrée par lequel un logiciel en interroge un autre pour échanger des données. Sa disponibilité dit si ce service répond.</p><h3 id="assertion" tabindex="-1">Assertion <a class="header-anchor" href="#assertion" aria-label="Permalink to &quot;Assertion&quot;">​</a></h3><p>L&#39;étape d&#39;un test qui vérifie un résultat attendu. Sans assertion, un test fait quelque chose mais ne contrôle rien : il passe toujours.</p><h3 id="assistant" tabindex="-1">Assistant <a class="header-anchor" href="#assistant" aria-label="Permalink to &quot;Assistant&quot;">​</a></h3><p>Le produit qu&#39;on utilise au quotidien (ChatGPT, Copilot, Claude.ai, Gemini) : une interface posée sur un harness, autour d&#39;un modèle.</p><h3 id="attente-fixe" tabindex="-1">Attente fixe <a class="header-anchor" href="#attente-fixe" aria-label="Permalink to &quot;Attente fixe&quot;">​</a></h3><p>Pause d&#39;une durée imposée dans un test automatisé (« attendre 5 secondes »). Elle ralentit le test et le rend instable : on attend plutôt un état précis de l&#39;écran.</p><h3 id="carte-de-test" tabindex="-1">Carte de test <a class="header-anchor" href="#carte-de-test" aria-label="Permalink to &quot;Carte de test&quot;">​</a></h3><p>Numéro de carte fourni par le prestataire de paiement pour la préproduction (ici la plage 9999 0000 0000 00NN) : il ne débite personne. Une vraie carte n&#39;a rien à faire dans un jeu de test.</p><h3 id="cas-limite" tabindex="-1">Cas limite <a class="header-anchor" href="#cas-limite" aria-label="Permalink to &quot;Cas limite&quot;">​</a></h3><p>Situation inhabituelle où la règle ne s&#39;applique pas comme d&#39;habitude : paiement refusé, demande annulée, article indisponible…</p><h3 id="checkpoint" tabindex="-1">Checkpoint <a class="header-anchor" href="#checkpoint" aria-label="Permalink to &quot;Checkpoint&quot;">​</a></h3><p>Question de contrôle à la fin d&#39;un exercice. Ta réponse reste dans ce navigateur.</p><h3 id="connecteur" tabindex="-1">Connecteur <a class="header-anchor" href="#connecteur" aria-label="Permalink to &quot;Connecteur&quot;">​</a></h3><p>Logiciel qui relie deux systèmes pour qu&#39;ils échangent des données : le connecteur PMS relie Lanterne au système de gestion de l&#39;hôtel. Un outil d&#39;IA peut aussi avoir des connecteurs vers Jira, GitLab ou ServiceNow : ils ne s&#39;utilisent que s&#39;ils sont autorisés.</p><h3 id="context-window" tabindex="-1">Context window <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;Context window&quot;">​</a></h3><p>Tout ce que le modèle « voit » au moment de répondre : consignes, historique, pièces jointes, résultats des tools.</p><h3 id="couverture-des-cas" tabindex="-1">Couverture des cas <a class="header-anchor" href="#couverture-des-cas" aria-label="Permalink to &quot;Couverture des cas&quot;">​</a></h3><p>Ce qu&#39;un jeu de tests ou de données exerce vraiment : chaque partition, chaque valeur limite, chaque combinaison de la table de décision. Un cas absent n&#39;est pas testé, même si le jeu est gros.</p><h3 id="critere-d-acceptation" tabindex="-1">Critère d&#39;acceptation <a class="header-anchor" href="#critere-d-acceptation" aria-label="Permalink to &quot;Critère d&#39;acceptation&quot;">​</a></h3><p>Condition vérifiable qu&#39;une user story doit remplir, souvent écrite « Étant donné…, quand…, alors… ».</p><h3 id="derive-de-contexte" tabindex="-1">Dérive de contexte <a class="header-anchor" href="#derive-de-contexte" aria-label="Permalink to &quot;Dérive de contexte&quot;">​</a></h3><p>Session qui se dégrade quand la context window se remplit d&#39;ajouts, de corrections et d&#39;informations périmées ou contradictoires : elle reste crédible mais s&#39;éloigne du besoin initial.</p><h3 id="dod-definition-of-done" tabindex="-1">DoD (Definition of Done) <a class="header-anchor" href="#dod-definition-of-done" aria-label="Permalink to &quot;DoD (Definition of Done)&quot;">​</a></h3><p>Liste de critères qu&#39;un travail doit remplir pour être considéré comme terminé.</p><h3 id="donnees-synthetiques" tabindex="-1">Données synthétiques <a class="header-anchor" href="#donnees-synthetiques" aria-label="Permalink to &quot;Données synthétiques&quot;">​</a></h3><p>Valeurs inventées qui respectent la forme et les règles des données réelles, sans en contenir aucune.</p><h3 id="dor-definition-of-ready" tabindex="-1">DoR (Definition of Ready) <a class="header-anchor" href="#dor-definition-of-ready" aria-label="Permalink to &quot;DoR (Definition of Ready)&quot;">​</a></h3><p>Liste de critères qu&#39;un besoin ou une user story doit remplir pour être pris en développement.</p><h3 id="drapeau-d-activation" tabindex="-1">Drapeau d&#39;activation <a class="header-anchor" href="#drapeau-d-activation" aria-label="Permalink to &quot;Drapeau d&#39;activation&quot;">​</a></h3><p>Réglage de configuration qui active une fonctionnalité pour certains hôtels seulement (ici, <code>depart-express</code> pour LYS-03), sans nouveau code à livrer.</p><h3 id="fuite-de-donnees" tabindex="-1">Fuite de données <a class="header-anchor" href="#fuite-de-donnees" aria-label="Permalink to &quot;Fuite de données&quot;">​</a></h3><p>Données confidentielles envoyées à un assistant non maîtrisé (version grand public).</p><h3 id="gherkin" tabindex="-1">Gherkin <a class="header-anchor" href="#gherkin" aria-label="Permalink to &quot;Gherkin&quot;">​</a></h3><p>Langage presque naturel (Soit / Quand / Alors) qui décrit un scénario de test ; chaque ligne, ou étape, est reliée à un morceau de code qui l&#39;exécute.</p><h3 id="go-no-go" tabindex="-1">Go / no-go <a class="header-anchor" href="#go-no-go" aria-label="Permalink to &quot;Go / no-go&quot;">​</a></h3><p>La décision de mettre en production ou non. Le QA apporte une recommandation et ce qui la fonde ; la décision appartient au comité (ici, Céline et Yann).</p><h3 id="grounding" tabindex="-1">Grounding <a class="header-anchor" href="#grounding" aria-label="Permalink to &quot;Grounding&quot;">​</a></h3><p>Ancrer la réponse dans des sources vérifiables plutôt que dans la « mémoire » du modèle.</p><h3 id="hallucination" tabindex="-1">Hallucination <a class="header-anchor" href="#hallucination" aria-label="Permalink to &quot;Hallucination&quot;">​</a></h3><p>Réponse fausse mais présentée avec assurance et vraisemblance.</p><h3 id="human-in-the-loop" tabindex="-1">Human-in-the-loop <a class="header-anchor" href="#human-in-the-loop" aria-label="Permalink to &quot;Human-in-the-loop&quot;">​</a></h3><p>Un humain qualifié valide la sortie de l&#39;IA avant qu&#39;elle soit utilisée.</p><h3 id="hypothese-de-cause" tabindex="-1">Hypothèse de cause <a class="header-anchor" href="#hypothese-de-cause" aria-label="Permalink to &quot;Hypothèse de cause&quot;">​</a></h3><p>Explication possible d&#39;une anomalie, pas encore démontrée. Dans un ticket, elle s&#39;écrit comme une hypothèse, séparée des faits observés.</p><h3 id="idempotence" tabindex="-1">Idempotence <a class="header-anchor" href="#idempotence" aria-label="Permalink to &quot;Idempotence&quot;">​</a></h3><p>Propriété d&#39;une opération qu&#39;on peut rejouer sans produire deux fois son effet : un règlement idempotent ne débite pas deux fois le client.</p><h3 id="journaux-logs" tabindex="-1">Journaux (logs) <a class="header-anchor" href="#journaux-logs" aria-label="Permalink to &quot;Journaux (logs)&quot;">​</a></h3><p>Traces écrites par un logiciel au fil de son travail : qui a demandé quoi, quand, avec quel résultat. Un identifiant de requête permet de suivre un échange de bout en bout.</p><h3 id="matrice-de-risques" tabindex="-1">Matrice de risques <a class="header-anchor" href="#matrice-de-risques" aria-label="Permalink to &quot;Matrice de risques&quot;">​</a></h3><p>Tableau qui classe les risques par probabilité et par impact, pour décider où tester le plus et le plus tôt.</p><h3 id="mcp-model-context-protocol" tabindex="-1">MCP (Model Context Protocol) <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP (Model Context Protocol)&quot;">​</a></h3><p>Un branchement standard qui donne des tools à un assistant IA : piloter un navigateur, lire un fichier, interroger un outil. L&#39;assistant agit ; tu vérifies ce qu&#39;il a fait.</p><h3 id="merge-request-mr-ou-pull-request" tabindex="-1">Merge request (MR) ou pull request <a class="header-anchor" href="#merge-request-mr-ou-pull-request" aria-label="Permalink to &quot;Merge request (MR) ou pull request&quot;">​</a></h3><p>Demande d&#39;intégrer une modification au code du produit. Fusionnée : la modification est intégrée ; brouillon : rien n&#39;est encore livré.</p><h3 id="module-partage" tabindex="-1">Module partagé <a class="header-anchor" href="#module-partage" aria-label="Permalink to &quot;Module partagé&quot;">​</a></h3><p>Code utilisé par plusieurs fonctionnalités : le modifier touche toutes celles qui l&#39;utilisent, même hors du sujet du sprint.</p><h3 id="niveau-de-test" tabindex="-1">Niveau de test <a class="header-anchor" href="#niveau-de-test" aria-label="Permalink to &quot;Niveau de test&quot;">​</a></h3><p>L&#39;étage où un test s&#39;exécute : unitaire (une petite partie du code, isolée), intégration (plusieurs composants ensemble), bout en bout (tout le parcours, comme un client), exploratoire, performance.</p><h3 id="non-regression" tabindex="-1">Non-régression <a class="header-anchor" href="#non-regression" aria-label="Permalink to &quot;Non-régression&quot;">​</a></h3><p>Vérifier que ce qui marchait avant marche encore après les changements du sprint.</p><h3 id="partition-d-equivalence" tabindex="-1">Partition d&#39;équivalence <a class="header-anchor" href="#partition-d-equivalence" aria-label="Permalink to &quot;Partition d&#39;équivalence&quot;">​</a></h3><p>Groupe de valeurs pour lesquelles le système se comporte de la même façon : on en teste un représentant plutôt que toutes.</p><h3 id="patrimoine-de-tests" tabindex="-1">Patrimoine de tests <a class="header-anchor" href="#patrimoine-de-tests" aria-label="Permalink to &quot;Patrimoine de tests&quot;">​</a></h3><p>L&#39;ensemble des tests que l&#39;équipe garde et rejoue. Chaque test ajouté se maintient : on n&#39;y fait entrer que des tests fiables et utiles.</p><h3 id="perimetre-non-teste" tabindex="-1">Périmètre non testé <a class="header-anchor" href="#perimetre-non-teste" aria-label="Permalink to &quot;Périmètre non testé&quot;">​</a></h3><p>Ce qui n&#39;a pas été testé dans une campagne (tests bloqués, non exécutés, hors campagne) et le risque que cela laisse. Il accompagne tout taux de réussite.</p><h3 id="pms" tabindex="-1">PMS <a class="header-anchor" href="#pms" aria-label="Permalink to &quot;PMS&quot;">​</a></h3><p>Système de gestion de l&#39;hôtel : réservations, état des chambres, note du client.</p><h3 id="po-product-owner" tabindex="-1">PO (Product Owner) <a class="header-anchor" href="#po-product-owner" aria-label="Permalink to &quot;PO (Product Owner)&quot;">​</a></h3><p>La personne qui porte le besoin et priorise : ici Yann. Le QA lui pose les questions sur le besoin et décide la priorité des anomalies avec lui.</p><h3 id="pre-autorisation" tabindex="-1">Pré-autorisation <a class="header-anchor" href="#pre-autorisation" aria-label="Permalink to &quot;Pré-autorisation&quot;">​</a></h3><p>Montant réservé sur la carte du client à son arrivée, encaissé au moment de régler la note.</p><h3 id="preproduction" tabindex="-1">Préproduction <a class="header-anchor" href="#preproduction" aria-label="Permalink to &quot;Préproduction&quot;">​</a></h3><p>Environnement qui reproduit la production pour tester avant la mise en service ; les vrais clients n&#39;y ont pas accès.</p><h3 id="prompt" tabindex="-1">Prompt <a class="header-anchor" href="#prompt" aria-label="Permalink to &quot;Prompt&quot;">​</a></h3><p>La demande envoyée au modèle, consignes comprises.</p><h3 id="recette" tabindex="-1">Recette <a class="header-anchor" href="#recette" aria-label="Permalink to &quot;Recette&quot;">​</a></h3><p>Vérification, avant la mise en service, que ce qui a été développé respecte les critères d&#39;acceptation. L&#39;environnement de recette sert à ces essais.</p><h3 id="reproductibilite" tabindex="-1">Reproductibilité <a class="header-anchor" href="#reproductibilite" aria-label="Permalink to &quot;Reproductibilité&quot;">​</a></h3><p>Capacité à refaire apparaître une anomalie en suivant les mêmes étapes, dite en « n fois sur m ».</p><h3 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h3><p>Une conversation ; elle accumule du contexte, utile ou parasite.</p><h3 id="severite-et-priorite" tabindex="-1">Sévérité et priorité <a class="header-anchor" href="#severite-et-priorite" aria-label="Permalink to &quot;Sévérité et priorité&quot;">​</a></h3><p>La sévérité mesure la gravité d&#39;une anomalie (bloquante, majeure, mineure, cosmétique) : le QA la propose. La priorité dit quand la corriger : elle se décide avec le PO.</p><h3 id="strategie-de-test" tabindex="-1">Stratégie de test <a class="header-anchor" href="#strategie-de-test" aria-label="Permalink to &quot;Stratégie de test&quot;">​</a></h3><p>Le choix de ce qu&#39;on teste, à quel niveau et à quelle profondeur, et de ce qu&#39;on laisse de côté, en fonction des risques.</p><h3 id="table-de-decision" tabindex="-1">Table de décision <a class="header-anchor" href="#table-de-decision" aria-label="Permalink to &quot;Table de décision&quot;">​</a></h3><p>Tableau qui liste les combinaisons de conditions et le résultat attendu pour chacune : aucune combinaison n&#39;est oubliée.</p><h3 id="taux-de-reussite" tabindex="-1">Taux de réussite <a class="header-anchor" href="#taux-de-reussite" aria-label="Permalink to &quot;Taux de réussite&quot;">​</a></h3><p>Part des tests réussis. Il n&#39;a de sens qu&#39;avec son dénominateur (tests exécutés ou prévus) et le périmètre non testé.</p><h3 id="test-de-fumee" tabindex="-1">Test de fumée <a class="header-anchor" href="#test-de-fumee" aria-label="Permalink to &quot;Test de fumée&quot;">​</a></h3><p>Petit nombre de tests rapides sur les parcours essentiels, pour savoir si une version vaut la peine d&#39;être testée plus loin.</p><h3 id="test-exploratoire" tabindex="-1">Test exploratoire <a class="header-anchor" href="#test-exploratoire" aria-label="Permalink to &quot;Test exploratoire&quot;">​</a></h3><p>Test mené en découvrant le système au fil de l&#39;eau, sans scénario écrit à l&#39;avance, avec des notes de session.</p><h3 id="test-flaky" tabindex="-1">Test flaky <a class="header-anchor" href="#test-flaky" aria-label="Permalink to &quot;Test flaky&quot;">​</a></h3><p>Test instable, qui réussit ou échoue au hasard sans que l&#39;application change. Tant qu&#39;il n&#39;est pas corrigé, son résultat ne prouve rien.</p><h3 id="timeout" tabindex="-1">Timeout <a class="header-anchor" href="#timeout" aria-label="Permalink to &quot;Timeout&quot;">​</a></h3><p>Délai d&#39;attente dépassé : un composant a cessé d&#39;attendre la réponse d&#39;un autre.</p><h3 id="token" tabindex="-1">Token <a class="header-anchor" href="#token" aria-label="Permalink to &quot;Token&quot;">​</a></h3><p>Morceau de mot traité par le modèle ; c&#39;est aussi l&#39;unité de facturation (≈ ¾ de mot en anglais).</p><h3 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h3><p>Capacités que le modèle peut appeler pendant sa réponse : recherche web, calcul, lecture de fichiers, Jira, Figma… (tool calling).</p><h3 id="user-story" tabindex="-1">User story <a class="header-anchor" href="#user-story" aria-label="Permalink to &quot;User story&quot;">​</a></h3><p>Description courte d&#39;un besoin du point de vue de l&#39;utilisateur : « En tant que…, je veux…, afin de… ».</p><h3 id="valeur-limite" tabindex="-1">Valeur limite <a class="header-anchor" href="#valeur-limite" aria-label="Permalink to &quot;Valeur limite&quot;">​</a></h3><p>Valeur à la frontière entre deux partitions d&#39;équivalence (100 % de la pré-autorisation, 7 jours pile) : c&#39;est là que les erreurs se cachent.</p>',113)])])}const m=a(o,[["render",n]]);export{h as __pageData,m as default};
